import React, { useState } from "react";
import { Link } from 'react-router-dom';

function AddCategories() {
    const [Name, setName] = useState('')


    async function AddCategory(event) {
        event.preventDefault()

        const toyData = {
            Name
        };

        if (!Name) {
            alert('Пожалуйста заполните все поля');
            return;
        } else {
            const response = await fetch('http://localhost:8084/category', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(toyData),
            });
            const data = await response.json()

            if (data) {
                alert('Катагория успешно добавлена')
                window.location.href = '/AddCategories'
            } else {
                alert('Ошибка при добавлении категорий')
            }
        }
    }
    if (localStorage.roles === "ADMIN" || localStorage.roles === "USER and ADMIN") {
        return (
            <div className="Singup">
                <h1>Добавление категорий</h1>
                <form onSubmit={AddCategory}>
                    <div className="form-text">
                        <h4>Название категорий</h4>
                        <input type="text" name="Name" id="Name" placeholder="Введите название категорий игрушки" minLength="3" value={Name} onChange={(e) => setName(e.target.value)} />
                    </div>
                    <br /><button type="submit" className="button" >добавить игрушку</button>
                    <br /> <Link to="/AddToys">Добавить категорию</Link>
                </form>
            </div>
        )
    } else {
        alert('У вас нету прав администратора')
        window.location.href = '/Home'
    }
}

export default AddCategories;
